package com.quincaisoft.integrations.application;import com.quincaisoft.finance.api.PeriodCloseGuard;import jakarta.persistence.EntityManager;import org.springframework.stereotype.Component;import java.time.LocalDate;
@Component public class ProviderPeriodGuard implements PeriodCloseGuard {private final EntityManager em;public ProviderPeriodGuard(EntityManager em){this.em=em;}public String domain(){return "providers";}public void verifyCanClose(LocalDate start,LocalDate end){long n=em.createQuery("select count(r) from ProviderIntentEntity r where r.environment<>'sandbox' and r.status not in ('CONFIRMED','FAILED') and r.businessDate between :start and :end",Long.class).setParameter("start",start).setParameter("end",end).getSingleResult();if(n>0)throw new IllegalStateException("Unresolved live provider collections prevent period closure");}}
